from common import *
case=read(R/'analysis/case_summary.json');rows=list(csv.DictReader((R/'analysis/formal_points.csv').open()));hetero=list(csv.DictReader((R/'analysis/seven_dataset_heterogeneity.csv').open()))
def table(head,body):return '| '+' | '.join(head)+' |\n| '+' | '.join(['---']*len(head))+' |\n'+''.join('| '+' | '.join(map(str,r))+' |\n' for r in body)
def pct(x):return f'{100*x:.2f}%'
def val(x):return '无增益，指标不适用' if x is None else pct(x)
def ref(x):return '当前固定GT10网格未覆盖' if not x else '被GT10 L='+x+'覆盖'
text=['# E193 自适应残差开关验证报告\n', '2026-10-29。默认仍为E99 GT10（WebVid soft-t1、Yandex hard）。本轮检查收益集中、理想选择省费空间、廉价特征能否实现三层问题。不是替换默认的盲确认。\n']
text+=['## 实际范围与计量\n', '七数据集已有E191真K1/100、L200实际返回作离线异质性复核；新性能是COCO、Deep10M、SIFT10M各固定2048query、两个真实K、102点×3=306完整T1轮。资格36点/36轮，开发GT10/SQ共12点/12轮另计；开发补全动作微计时为6组×4000query×3=72000次。CPU15，四个数学库线程变量=1，进程采样和native边界均核线程1；方法串行，训练不与正式性能并行。\n', '所有新Recall与QPS均来自同一2048窗口实际包。GT10 L固定200/202/204/208/216/232/256/272/288/304/320/400。另测B32、全开REUSE-SQ、同条件全关GATE-OFF、GT知情GATE-ORACLE、冻结GATE-LEARNED。计时包括Batch初始化/分配、路由/主搜索、特征提取/模型推断/开关、启用时的残差、六数组复制与销毁；预载只读模型及mask，读取GT、落盘、哈希和核验在外。ORACLE查GT得到正净收益mask，真实付在线分支费用，但不可部署。它是保留全部正收益的理想参考，非批处理缓存/全局最优门控的数学上界。\n', '复用原图、base、原L2/raw-IP、GT10、SQ8代码与前12K残差标签的块表。三路各8块+主结果最多8块，候选块≤32、代码扫描≤2048、精确评分≤96，strict merge。B32保持旧16K，仅作正式参考，不参与新门拟合/校准。\n']
text+=['## 1. 收益是否集中\n',table(['数据集','K','旧窗口n','新增正确成员','改善query比例','损失成员'],[[LABEL[r['dataset']],r['K'],r['n'],r['net_members'],pct(float(r['oracle_on_rate'])),r['lost']] for r in hetero]),'\n旧包没有损伤。Deep/SIFT的K100全部收益集中在8.05%/7.42%的query，存在大量可跳过动作；COCO K100覆盖71.7%，选择性省费天然较小。K1时多数数据的可救查询极少，Deep/SIFT在这个L200后端下没有收益；不能将它外推其他L或新来源。该表只描述已有结果，不新增七集QPS。\n']
text+=['## 2. 理想开关与真实廉价门的完整费用\n',table(['数据集/K','SQ增益pp','理想启用','学习启用','学习保留增益','全开QPS','理想QPS','学习QPS'],[[f"{LABEL[v['dataset']]}/{v['K']}",f"{v['sq_gain_pp']:.4f}",pct(v['ideal_on_rate']),pct(v['learned_on_rate']),val(v['learned_gain_retained']),f"{v['sq_qps']:.2f}",f"{v['ideal_qps']:.2f}",f"{v['learned_qps']:.2f}"] for v in case]),'\nQPS是三轮完整wall的中位数；增益保留以新增正确GT成员为分母，不能与主Recall保留率混淆。理想门保留本窗口SQ的全部增益并跳过零收益动作。模型全关回退不意味着额外预测成功。\n']
text+=['## 3. 与更大L的GT10和B32逐点比较\n']
for v in case:
 ds=v['dataset'];K=v['K'];rr=[r for r in rows if r['dataset']==ds and int(r['K'])==K and int(r['L'])==200]
 text += [f"### {LABEL[ds]} / K={K}\n",table(['方法/L','Recall%','新增/损失成员','启用%','完整us/query','QPS[三轮范围]','扫描代码/q','精确补评分/q'],[[r['method']+'/200',f"{100*float(r['recall']):.4f}",r['rescued']+'/'+r['lost'],f"{100*float(r['on_rate']):.2f}",f"{float(r['wall_us']):.2f}",f"{float(r['qps']):.2f} [{float(r['qps_min']):.2f},{float(r['qps_max']):.2f}]",f"{float(r['scans_per_query']):.2f}",f"{float(r['exact_per_query']):.2f}"] for r in rr]),f"\n理想门：{ref(v['ideal_GT_cover'])}；学习门：{ref(v['learned_GT_cover'])}；B32是否同时覆盖学习/理想门：{v['learned_B32_cover']}/{v['ideal_B32_cover']}。三轮GT最慢仍快于候选最快的覆盖L分别为`{v['ideal_GT_all3_cover'] or '无'}`、`{v['learned_GT_all3_cover'] or '无'}`。这只是实测范围，不是统计置信区间。\n"]
 controls=[]
 for tag in ['ideal','learned']:
  L=v[tag+'_next_GT_L']
  if L is not None:
   r=next(r for r in rows if r['dataset']==ds and int(r['K'])==K and r['method']=='GT10' and int(r['L'])==L);controls.append([tag,L,f"{100*float(r['recall']):.4f}",f"{float(r['qps']):.2f}"])
 text += [table(['达到候选质量的最快网格GT10','L','Recall%','QPS'],controls) if controls else '预定网格没有达到对应质量的GT10点。\n']
text+=['## 4. 拟合、校准和可预测性\n','新残差块表读取合法16K角色的前12K。门使用相对角色[12000,14000)拟合、[14000,16000)校准，彼此及test不混用；旧GT10监督可能用过16K，因此这不是对全部系统监督全新数据。test是历史公开窗口的固定随机子集，不能叫新盲测试。\n','两组特征：ROUTE为原route的3分数摘要、query范数等5项；POST增加主搜索D的分位与跨度，共12项。候选岭回归lambda10和深度3 CART；拟合目标是净新增GT成员与实际动作微秒双头，预测收益/预测成本排序。每模型仅7个预定拟合分位阈值，以校准保留≥90%正收益、估计费用最小选定；允许全开/全关回退。固定0.5us仅为校准估计的推断预算，实际完整计时未以该常数代替在线费用。\n',table(['数据/K','选中模型/特征数','校准增益保留','校准启用','动作平均us','理想动作us/q','学习动作us/q'],[[f"{LABEL[v['dataset']]}/{v['K']}",f"{v['selected_kind']}/{v['selected_nf']}",val(v['cal_gain_retained']),pct(v['cal_learned_on_rate']),f"{v['cal_action_us']:.2f}",f"{v['cal_oracle_action_us']:.2f}",f"{v['cal_learned_action_us']:.2f}"] for v in case]),'\n动作微计时对同一实际主返回重放三遍complete，query设置与数组复制在计时外，逐query取三遍中位数；它用于选择、不能与批次完整wall作精确可加分解。实际是否划算以上表的完整wall为准。本轮门在主搜索后决策，复用route/main状态；未新增独立预查询probe。选中的非回退门均用了POST，不能据此声称纯查询前开关已成功。\n']
learncov=sum(bool(v['learned_GT_cover']) for v in case);idealcov=sum(bool(v['ideal_GT_cover']) for v in case);combined=sum(v['learned_combined_cover'] for v in case);idealcombined=sum(v['ideal_combined_cover'] for v in case);positive=[v for v in case if v['sq_rescued']>0];positive_ideal_covered=sum(v['ideal_combined_cover'] for v in positive)
text += ['## 5. 结论与边界\n',f'本次固定矩阵，学习门有{learncov}/6组被GT10的Recall和中位QPS同时覆盖，计入B32参考后为{combined}/6组；有残差增益的{len(positive)}组中，理想门被GT10/B32覆盖{positive_ideal_covered}组；另外两组Deep/SIFT K1没有增益，跳过即可，SIFT全关参考的微小QPS差不能算新优化潜力。未覆盖只代表固定网格上的探索空间，仍需检查B32、三轮范围、稀少事件和新合法query，不能直接替换默认。\n','你的两个方向可以并行推进：后端降低动作费用/提高每次动作净收益；门控降低无效启用。全开不优不能作为禁止研究开关的前提。收益集中已经得到直接支持，廉价可识别和完整Recall–QPS胜出须分别检验。本轮只验证了12种固定模型配置（6组各候选2特征×2模型、阈值只在校准选择）的实现，负结果不能证明所有自适应算法都不可能。\n','更准确的下一步依据应是每组当前全收益保留理想参考与学习门的差距：理想参考有空间时研究可识别性；该参考也被覆盖时优先检查固定开关费用、动作费用或候选支持。这里没有测完所有舍弃部分收益的oracle策略，不能据此证明其他召回取舍或更快条件核全部无效。后续若另开实验，需要另冻训练/校准/测试角色及完整计时，不自动追加到通过。默认不变，本轮固定范围已经收口。\n','校准预定保留>=90%增益只测试了一个收益偏好，其他费用/召回偏好未正式测量。所有结论限定同一图/画像、公共query曝光、小窗口，独立实现核验由同一执行者完成，非独立人员复现。旧E192排除证书针对原全开完整费用，本轮改变启用条件，因此两者不矛盾。GT知情门从未冒充可上线预测器。\n']
# Correct candidate accounting: 24 fitted model bases across six cases, 168 calibrated threshold candidates.
text=[t.replace('12种固定模型配置（6组各候选2特征×2模型、阈值只在校准选择）','六组固定候选族（每组2特征×2模型×7阈值，共168个校准候选；阈值只在校准选择）') for t in text]
text += ['## 证据与复核\n','[冻结协议](protocol.md) · [预先冻结](freeze.json) · [正式模型/代码冻结](formal_freeze.json) · [全部102点](analysis/formal_points.csv) · [六组摘要](analysis/case_summary.csv) · [动作费用](analysis/action_cost.csv) · [七集异质性](analysis/seven_dataset_heterogeneity.csv) · [拟合与候选](analysis/) · [配置](configs/) · [源码](src/benchmark.cpp) · [核验](reviews/) · [状态](state.json)\n','正式包三轮bits/SHA一致，所有gated查询逐query严格等于实际GT10或实际SQ对应分支；Python独立核Recall、损伤、gate推断、访问量、包hash，并与E191同ID样本的GT10/B32/SQ四数组逐字节对齐。native全query全排序SQ合并oracle另核。原E192/E191科学原件与PDF保留；根文档旧字节按source_before与SHA迁移核验，旧seal不回写。\n']
(R/'report_zh.md').write_text('\n'.join(text));dump(R/'analysis/verdict.json',dict(learned_GT10_covered_cases=learncov,ideal_GT10_covered_cases=idealcov,learned_GT10_or_B32_covered_cases=combined,ideal_GT10_or_B32_covered_cases=idealcombined,positive_gain_cases=len(positive),positive_gain_ideal_covered_cases=positive_ideal_covered,cases=6,default_changed=False,status='EXPLORATORY_NO_DEFAULT_CHANGE'))
print('E193_REPORT_WRITTEN')
